from pathlib import Path
TABLES={}
def t(name,columns,constraints=(),indexes=()):
    TABLES[name]={'columns':columns,'constraints':list(constraints),'indexes':list(indexes)}
ID=('id','uuid PRIMARY KEY DEFAULT gen_random_uuid()','내부 불변 식별자')
CREATED=('created_at','timestamptz NOT NULL DEFAULT now()','서버 생성 시각')
VERSION=('version','bigint NOT NULL DEFAULT 1 CHECK (version > 0)','API가 expectedVersion 검증 후 +1')
def fk(name,target,nullable=False,description='참조 대상'):
    return (name,f'uuid {"" if nullable else "NOT NULL "}REFERENCES {target}(id) ON DELETE NO ACTION',description)
def state(values,default):return "text NOT NULL DEFAULT '"+default+"' CHECK (state IN ("+','.join("'"+s+"'" for s in values.split())+'))'
def status(values,default):return state(values,default).replace('state IN','status IN')

