def write_ddl(root):
    pre="""-- At that place v0.3 / PostgreSQL 16. Empty database baseline, not application implementation.
-- Run: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f 001_initial.sql
BEGIN;
SELECT pg_advisory_xact_lock(74103102);
CREATE SCHEMA atp;
REVOKE ALL ON SCHEMA atp FROM PUBLIC;
SET LOCAL search_path = atp, pg_catalog;
"""
    body=[]
    for name,d in TABLES.items():
        body.append('CREATE TABLE '+name+' (\n  '+',\n  '.join([c[0]+' '+c[1] for c in d['columns']]+d['constraints'])+'\n);')
        for c in d['columns']:
            comment=c[2].replace('삭제 뒤에도 유지','삭제 뒤에도 유지').replace('원본 직접 배포 금지','원본 직접 배포 금지').replace("'","''")
            body.append(f"COMMENT ON COLUMN {name}.{c[0]} IS '{comment}';")
        body+= [sql+';' for sql in d['indexes']]
    body.append('ALTER TABLE groups ADD CONSTRAINT groups_cover_asset_fk FOREIGN KEY(cover_asset_id) REFERENCES assets(id) ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED;')
    # 소유 그룹을 혼동하는 대표사진 FK는 교차 테이블 guard로 검증한다.
    guards=(Path(__file__).parent/'schema_guards.sql').read_text()
    out=Path(root)/'부록/DB/001_initial.sql'
    out.write_text(pre+'\n\n'.join(body)+'\n'+guards+'\nCOMMIT;\n')
    return out
